def mrg_dct(pr_dct, scnd_src):
    rslt = pr_dct.copy()
    for k, v in scnd_src.items():
        if k in rslt and isinstance(rslt[k], dict) and isinstance(v, dict):
            rslt[k] = v
        else:
            rslt[k] = v
